CREATE TABLE porthole_migration_records (
 kind TEXT NOT NULL, id TEXT NOT NULL, body TEXT NOT NULL CHECK(json_valid(body)),
 revision TEXT NOT NULL, PRIMARY KEY(kind,id)
);
CREATE TRIGGER porthole_migration_insert AFTER INSERT ON porthole_migration_records WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,action,lower(hex(randomblob(16))),NULL,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_migration_update AFTER UPDATE ON porthole_migration_records WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,action,lower(hex(randomblob(16))),NULL,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_migration_delete AFTER DELETE ON porthole_migration_records WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,action,lower(hex(randomblob(16))),NULL,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

-- Export approvals are installation-local authority and are never restored.
CREATE TABLE porthole_signal_exports (
 id TEXT PRIMARY KEY, owner_ref TEXT NOT NULL, owner_revision INTEGER NOT NULL,
 created_at INTEGER NOT NULL, approved_at INTEGER, state TEXT NOT NULL CHECK(state IN ('preview','approved','cancelled')),
 selection TEXT NOT NULL CHECK(json_valid(selection)), snapshot INTEGER NOT NULL,
 estimate TEXT NOT NULL CHECK(json_valid(estimate)), credential_ref TEXT
);
CREATE TRIGGER porthole_signal_export_fact_insert AFTER INSERT ON porthole_signal_exports WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'signals.export-preview',NEW.id,0,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_signal_export_fact_update AFTER UPDATE ON porthole_signal_exports WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'signals.export-'||NEW.state,NEW.id,1,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

-- Stable identities survive installation archives. Exclusions only accumulate.
CREATE TABLE porthole_export_exclusions (
 record_id TEXT PRIMARY KEY, excluded_at INTEGER NOT NULL CHECK(excluded_at>=0)
);
CREATE TRIGGER porthole_export_exclusion_fact AFTER INSERT ON porthole_export_exclusions WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'signals.export-excluded',substr(NEW.record_id,1,36),0,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_export_exclusions_no_delete BEFORE DELETE ON porthole_export_exclusions BEGIN
 SELECT RAISE(ABORT,'export_exclusions_append_only');
END;
CREATE TRIGGER porthole_export_exclusions_no_rollback BEFORE UPDATE ON porthole_export_exclusions WHEN NEW.record_id!=OLD.record_id OR NEW.excluded_at<OLD.excluded_at BEGIN
 SELECT RAISE(ABORT,'export_exclusions_append_only');
END;

CREATE TABLE porthole_dashboards(id TEXT PRIMARY KEY,name TEXT NOT NULL,scope TEXT NOT NULL CHECK(json_valid(scope)),body TEXT NOT NULL CHECK(json_valid(body)),revision INTEGER NOT NULL CHECK(revision>0),state TEXT NOT NULL CHECK(state IN ('active','archived','quarantined')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE porthole_dashboard_versions(id TEXT NOT NULL,name TEXT NOT NULL,scope TEXT NOT NULL CHECK(json_valid(scope)),body TEXT NOT NULL CHECK(json_valid(body)),revision INTEGER NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(id,revision));
CREATE TRIGGER porthole_dashboard_insert AFTER INSERT ON porthole_dashboards BEGIN
 INSERT OR IGNORE INTO porthole_dashboard_versions SELECT NEW.id,NEW.name,NEW.scope,NEW.body,NEW.revision,NEW.state,NEW.created_at,NEW.updated_at;
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'dashboards.create',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_dashboard_update AFTER UPDATE ON porthole_dashboards BEGIN
 INSERT OR IGNORE INTO porthole_dashboard_versions SELECT NEW.id,NEW.name,NEW.scope,NEW.body,NEW.revision,NEW.state,NEW.created_at,NEW.updated_at;
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'dashboards.change',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

CREATE TABLE porthole_dashboard_publications(
 id TEXT PRIMARY KEY,dashboard_id TEXT NOT NULL,source_revision INTEGER NOT NULL CHECK(source_revision>0),
 owner_id TEXT NOT NULL,owner_revision INTEGER NOT NULL CHECK(owner_revision>0),operator_version INTEGER NOT NULL CHECK(operator_version>0),
 projection TEXT NOT NULL CHECK(json_valid(projection)),source_review TEXT NOT NULL CHECK(json_valid(source_review)),allowed_origins TEXT NOT NULL CHECK(json_valid(allowed_origins)),
 expires_at INTEGER NOT NULL,digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('draft','published','revoked','quarantined')),
 revision INTEGER NOT NULL CHECK(revision>0),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,approved_at INTEGER,revoked_at INTEGER
);
CREATE INDEX porthole_publication_dashboard ON porthole_dashboard_publications(dashboard_id,created_at);
CREATE TRIGGER porthole_publication_immutable BEFORE UPDATE ON porthole_dashboard_publications
 WHEN NEW.id!=OLD.id OR NEW.dashboard_id!=OLD.dashboard_id OR NEW.source_revision!=OLD.source_revision
 OR NEW.owner_id!=OLD.owner_id OR NEW.owner_revision!=OLD.owner_revision OR NEW.operator_version!=OLD.operator_version
 OR NEW.projection!=OLD.projection OR NEW.source_review!=OLD.source_review OR NEW.allowed_origins!=OLD.allowed_origins
 OR NEW.expires_at!=OLD.expires_at OR NEW.digest!=OLD.digest OR NEW.created_at!=OLD.created_at
 BEGIN SELECT RAISE(ABORT,'immutable_publication'); END;
CREATE TRIGGER porthole_publication_insert AFTER INSERT ON porthole_dashboard_publications BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'dashboards.publication-preview',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_publication_update AFTER UPDATE ON porthole_dashboard_publications BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,CASE WHEN NEW.state='published' THEN 'dashboards.publication-approve' ELSE 'dashboards.publication-revoke' END,NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

ALTER TABLE rer_dependency_installation ADD COLUMN keys_sealed INTEGER NOT NULL DEFAULT 0 CHECK(keys_sealed IN (0,1));
-- Nonsecret version history lets restored rows name an unavailable retired key
-- without confusing ciphertext tampering or a wrong current secret with restore.
ALTER TABLE rer_dependency_installation ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(key_ids) AND json_type(key_ids)='array');

CREATE TABLE porthole_baggage_policy (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),
 allowed_keys TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(allowed_keys)),
 attribute_keys TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attribute_keys)),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 changed_at INTEGER NOT NULL DEFAULT 0
);
INSERT INTO porthole_baggage_policy(singleton) VALUES(1);
CREATE TRIGGER porthole_baggage_audit AFTER UPDATE ON porthole_baggage_policy WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_entity_refs(kind,key_ref,entity_ref) VALUES('porthole_baggage_policy',NEW.singleton,lower(hex(randomblob(16)))) ON CONFLICT DO NOTHING;
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,action,(SELECT entity_ref FROM porthole_entity_refs WHERE kind='porthole_baggage_policy' AND key_ref=NEW.singleton),NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

-- Retain earlier unknown submissions independently of the deduplication clock.
ALTER TABLE porthole_health_notices ADD COLUMN had_uncertain INTEGER NOT NULL DEFAULT 0 CHECK(had_uncertain IN (0,1));
-- Older pending attempts do not carry sufficient outcome history to disprove
-- acceptance. Preserve that uncertainty when a later attempt is refused.
UPDATE porthole_health_notices SET had_uncertain=1 WHERE state IN ('sending','uncertain') OR (state='pending' AND first_attempt_at IS NOT NULL);

-- Private transport identity is operational custody, omitted from both archive
-- projections. Legacy work without a binding proof requires owner review.
ALTER TABLE porthole_health_notices ADD COLUMN transport_grant TEXT CHECK(transport_grant IS NULL OR (length(transport_grant)=64 AND transport_grant NOT GLOB '*[^0-9a-f]*'));

-- Receipt acceptance and its private audit fact commit atomically.
CREATE TRIGGER porthole_notice_reconciled AFTER UPDATE OF state ON porthole_health_notices
 WHEN OLD.state='uncertain' AND NEW.state='accepted' AND EXISTS(SELECT 1 FROM porthole_audit_context WHERE action='integration.notice-reconcile') BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,action,NEW.id,NEW.configuration_revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
 END;

-- Stable batch tombstones accompany archives; never retain the identifier.
CREATE TABLE porthole_erased_batches (
 id TEXT PRIMARY KEY, content_digest TEXT NOT NULL CHECK(length(content_digest)=64), erased_at INTEGER NOT NULL CHECK(erased_at>=0)
);
CREATE TRIGGER porthole_erased_batch_fact AFTER INSERT ON porthole_erased_batches
 WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'privacy.erase-batch',NEW.id,NULL,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

