CREATE TABLE porthole_follow_up (
 id TEXT PRIMARY KEY, source TEXT NOT NULL UNIQUE, kind TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(json_valid(scope)), owner_id TEXT,
 state TEXT NOT NULL CHECK(state IN ('open','blocked','resolved')),
 reason TEXT NOT NULL, next_action TEXT NOT NULL, due_at INTEGER NOT NULL,
 guard_id TEXT, guard_revision INTEGER, generation INTEGER NOT NULL DEFAULT 1,
 revision INTEGER NOT NULL DEFAULT 1, reminders INTEGER NOT NULL DEFAULT 0 CHECK(reminders IN (0,1)),
 suppressed_until INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE porthole_follow_up_events (
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES porthole_follow_up(id),
 generation INTEGER NOT NULL, kind TEXT NOT NULL, actor_id TEXT, detail TEXT NOT NULL, occurred_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX porthole_follow_up_one_reminder ON porthole_follow_up_events(task_id,generation) WHERE kind='reminder';
CREATE TRIGGER porthole_follow_up_removal BEFORE UPDATE OF status ON oa_operators
 WHEN NEW.status='inactive' AND EXISTS(SELECT 1 FROM porthole_follow_up WHERE owner_id=OLD.id AND state!='resolved')
 BEGIN SELECT RAISE(ABORT,'follow_up_handover_required'); END;
CREATE TRIGGER porthole_follow_up_fact AFTER UPDATE ON porthole_follow_up WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'follow-up.change',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_follow_up_scope_change BEFORE UPDATE OF role,scope ON porthole_members
 WHEN (NEW.role!=OLD.role OR NEW.scope!=OLD.scope) AND EXISTS(SELECT 1 FROM porthole_follow_up WHERE owner_id=OLD.operator_id AND state!='resolved')
 BEGIN SELECT RAISE(ABORT,'follow_up_handover_required'); END;
CREATE TRIGGER porthole_follow_up_open_fact AFTER INSERT ON porthole_follow_up WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'follow-up.open',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_follow_up_transition AFTER UPDATE OF state ON porthole_follow_up WHEN NEW.state!=OLD.state BEGIN
 INSERT INTO porthole_follow_up_events VALUES(lower(hex(randomblob(16))),NEW.id,NEW.generation,CASE WHEN NEW.state='resolved' THEN 'recovery' ELSE 'regression' END,NULL,NEW.reason,NEW.updated_at);
END;

DROP TRIGGER porthole_follow_up_scope_change;
-- Authority revocation never waits for work review. Keep the original work and
-- its scope, suspend assignment, and require a current native owner to review.
CREATE TRIGGER porthole_follow_up_authority_changed AFTER UPDATE OF role,scope ON porthole_members
 WHEN NEW.role!=OLD.role OR NEW.scope!=OLD.scope BEGIN
 INSERT INTO porthole_follow_up_events
 SELECT lower(hex(randomblob(16))),id,generation,'authority-change',NULL,'Assignee authority changed; assignment suspended for native owner review.',CAST(unixepoch('subsec')*1000 AS INTEGER)
 FROM porthole_follow_up WHERE owner_id=OLD.operator_id AND state!='resolved';
 UPDATE porthole_follow_up SET owner_id=NULL,state='blocked',reason='Assignee authority changed; native owner review required.',next_action='Review an active successor with the original work scope, or explicitly keep this work unassigned.',revision=revision+1,updated_at=CAST(unixepoch('subsec')*1000 AS INTEGER)
 WHERE owner_id=OLD.operator_id AND state!='resolved';
END;

-- Revisions are immutable definitions. Evaluation reads retained source data
-- each time so late arrivals and erasure cannot leave a stale healthy report.
CREATE TABLE porthole_slo_versions (
 id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), name TEXT NOT NULL,
 definition TEXT NOT NULL CHECK(json_valid(definition)), owner_id TEXT NOT NULL,
 created_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','quarantined')),
 PRIMARY KEY(id,revision)
);
CREATE TRIGGER porthole_slo_fact AFTER INSERT ON porthole_slo_versions WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'slo.revision',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

-- Imported-target erasure is explicit, local and separately approved.
-- Receipts contain no source IDs, target IDs, original names or source values.
CREATE TABLE porthole_migration_erasure_fences (
 receipt_id TEXT PRIMARY KEY CHECK(length(receipt_id)=36 AND receipt_id NOT GLOB '*[^a-f0-9-]*'),
 inventory_digest TEXT NOT NULL CHECK(length(inventory_digest)=64 AND inventory_digest NOT GLOB '*[^a-f0-9]*'),
 erased_at INTEGER NOT NULL CHECK(typeof(erased_at)='integer' AND erased_at>=0)
);
CREATE TRIGGER porthole_migration_erasure_immutable_insert BEFORE INSERT ON porthole_migration_erasure_fences
 WHEN EXISTS(SELECT 1 FROM porthole_migration_erasure_fences WHERE receipt_id=NEW.receipt_id AND (inventory_digest!=NEW.inventory_digest OR erased_at!=NEW.erased_at))
 BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_FENCE_CHANGED'); END;
CREATE TRIGGER porthole_migration_erasure_immutable_update BEFORE UPDATE ON porthole_migration_erasure_fences
 WHEN NEW.receipt_id IS NOT OLD.receipt_id OR NEW.inventory_digest IS NOT OLD.inventory_digest OR NEW.erased_at IS NOT OLD.erased_at
 BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_FENCE_CHANGED'); END;
CREATE TRIGGER porthole_migration_erasure_immutable_delete BEFORE DELETE ON porthole_migration_erasure_fences
 BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_FENCE_CHANGED'); END;
-- A committed checkpoint is audited in its transaction even if HTTP delivery
-- fails. The only entity reference is its opaque receipt, never source content.
CREATE TRIGGER porthole_migration_erasure_audit AFTER INSERT ON porthole_migration_erasure_fences
 WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,action,NEW.receipt_id,NULL,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
-- Local concurrency control only; never portable permission or a source record.
CREATE TABLE porthole_migration_erasure_state (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0)
);
INSERT INTO porthole_migration_erasure_state(singleton,revision) VALUES(1,0);
-- Local acknowledgement recovery binds a digest to the exact reviewed request.
-- It carries only hashes and an opaque receipt; source approval never transfers.
CREATE TABLE porthole_migration_erasure_replays (
 inventory_digest TEXT PRIMARY KEY CHECK(length(inventory_digest)=64 AND inventory_digest NOT GLOB '*[^a-f0-9]*'),
 selection_digest TEXT NOT NULL CHECK(length(selection_digest)=64 AND selection_digest NOT GLOB '*[^a-f0-9]*'),
 receipt_id TEXT NOT NULL REFERENCES porthole_migration_erasure_fences(receipt_id)
);
