-- Reviewed bounded definitions apply only to subsequently accepted envelopes.
CREATE TABLE porthole_metric_previews(id TEXT PRIMARY KEY,operator_id TEXT NOT NULL,session_id TEXT NOT NULL,definition TEXT NOT NULL,digest TEXT NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER,target_id TEXT NOT NULL,expected_revision INTEGER NOT NULL);
CREATE TABLE porthole_metric_rules(id TEXT NOT NULL,revision INTEGER NOT NULL,definition TEXT NOT NULL,from_sequence INTEGER NOT NULL,created_at INTEGER NOT NULL,owner_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','quarantined')),PRIMARY KEY(id,revision));
CREATE TABLE porthole_metric_points(rule_id TEXT NOT NULL,revision INTEGER NOT NULL,batch_id TEXT NOT NULL,ordinal INTEGER NOT NULL,dimensions TEXT NOT NULL,value REAL,valid INTEGER NOT NULL,event_time_ns TEXT NOT NULL,trace_id TEXT NOT NULL,span_id TEXT NOT NULL,PRIMARY KEY(rule_id,revision,batch_id,ordinal));
CREATE INDEX porthole_metric_window ON porthole_metric_points(rule_id,revision,event_time_ns);
CREATE TRIGGER porthole_metric_batch_erasure AFTER DELETE ON porthole_ingest_batches BEGIN DELETE FROM porthole_metric_points WHERE batch_id=OLD.id; END;
CREATE TRIGGER porthole_metric_rule_fact AFTER INSERT ON porthole_metric_rules WHEN EXISTS(SELECT 1 FROM porthole_audit_context) BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'metrics.rule-approve',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

CREATE TRIGGER porthole_metric_record_erasure AFTER DELETE ON porthole_telemetry_records BEGIN DELETE FROM porthole_metric_points WHERE batch_id=OLD.batch_id AND ordinal=OLD.ordinal; END;
CREATE TRIGGER porthole_metric_envelope_erasure AFTER UPDATE OF records ON porthole_ingest_batches WHEN NEW.records='[]' AND NEW.record_count=0 BEGIN DELETE FROM porthole_metric_points WHERE batch_id=NEW.id; END;

CREATE TABLE IF NOT EXISTS agent_door_state (
  id INTEGER PRIMARY KEY CHECK(id=1), envelope TEXT, local_document TEXT,
  local_revision INTEGER NOT NULL DEFAULT 0, local_paused INTEGER NOT NULL DEFAULT 0,
  decision_lock TEXT, decision_until INTEGER
);
CREATE TABLE IF NOT EXISTS agent_door_agents (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, specialist TEXT, sponsor TEXT NOT NULL,
  sponsor_name TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0,
  window INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS agent_door_audit (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, at TEXT NOT NULL,
  agent TEXT NOT NULL, classes TEXT NOT NULL, row TEXT NOT NULL, evidence TEXT
);
CREATE INDEX IF NOT EXISTS agent_door_audit_agent ON agent_door_audit(agent,sequence);
CREATE TABLE IF NOT EXISTS agent_door_calls (
  agent TEXT NOT NULL, key TEXT NOT NULL, digest TEXT NOT NULL, decision_id TEXT NOT NULL,
  created_at INTEGER NOT NULL, state TEXT NOT NULL, outcome TEXT, PRIMARY KEY(agent,key)
);
CREATE TABLE IF NOT EXISTS agent_door_approvals (
  id TEXT PRIMARY KEY, state TEXT NOT NULL, saved TEXT NOT NULL, approvals TEXT NOT NULL DEFAULT '[]',
  result TEXT, version INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS agent_door_reviews (
  id TEXT PRIMARY KEY, state TEXT NOT NULL, saved TEXT NOT NULL, marked_by TEXT, marked_at TEXT
);
CREATE TABLE IF NOT EXISTS agent_door_events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, uri TEXT NOT NULL, event TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS agent_door_events_uri ON agent_door_events(uri,sequence);
CREATE TABLE IF NOT EXISTS agent_door_usage (
  decision_id TEXT PRIMARY KEY, at INTEGER NOT NULL, seed TEXT NOT NULL, specialist TEXT, agent TEXT NOT NULL,
  classes TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS agent_door_usage_day ON agent_door_usage(at);

CREATE TABLE porthole_notebooks (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_ref TEXT NOT NULL, author_ref TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(json_valid(scope)), body TEXT NOT NULL CHECK(json_valid(body)),
 revision INTEGER NOT NULL CHECK(revision>0), state TEXT NOT NULL CHECK(state IN ('active','quarantined')),
 created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE porthole_notebook_versions (
 id TEXT NOT NULL, name TEXT NOT NULL, owner_ref TEXT NOT NULL, author_ref TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(json_valid(scope)), body TEXT NOT NULL CHECK(json_valid(body)),
 revision INTEGER NOT NULL CHECK(revision>0), state TEXT NOT NULL CHECK(state IN ('active','quarantined')),
 created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(id,revision)
);
CREATE TABLE porthole_notebook_shares (
 notebook_id TEXT NOT NULL REFERENCES porthole_notebooks(id), kind TEXT NOT NULL CHECK(kind IN ('member','team')),
 target TEXT NOT NULL, owner_ref TEXT NOT NULL, owner_revision INTEGER NOT NULL, operator_version INTEGER NOT NULL,
 created_at INTEGER NOT NULL, PRIMARY KEY(notebook_id,kind,target)
);
CREATE TRIGGER porthole_notebook_created AFTER INSERT ON porthole_notebooks BEGIN
 INSERT OR IGNORE INTO porthole_notebook_versions SELECT NEW.id,NEW.name,NEW.owner_ref,NEW.author_ref,NEW.scope,NEW.body,NEW.revision,NEW.state,NEW.created_at,NEW.updated_at;
END;
CREATE TRIGGER porthole_notebook_revised AFTER UPDATE ON porthole_notebooks BEGIN
 INSERT OR IGNORE INTO porthole_notebook_versions SELECT NEW.id,NEW.name,NEW.owner_ref,NEW.author_ref,NEW.scope,NEW.body,NEW.revision,NEW.state,NEW.created_at,NEW.updated_at;
END;

CREATE TABLE bs_settings (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  rev INTEGER NOT NULL DEFAULT 0,
  document TEXT,
  applied_at TEXT,
  stopped INTEGER NOT NULL DEFAULT 0 CHECK(stopped IN(0,1)),
  token TEXT NOT NULL DEFAULT ''
);
CREATE TABLE bs_overrides (
  field TEXT PRIMARY KEY CHECK(field IN('display_name','owner_name','brand_color','logo','timezone')),
  value TEXT NOT NULL,
  actor TEXT NOT NULL,
  changed_at TEXT NOT NULL
);
CREATE TABLE bs_logo (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  sha256 TEXT NOT NULL,
  type TEXT NOT NULL,
  bytes BLOB NOT NULL
);
CREATE TABLE bs_team (
  email TEXT PRIMARY KEY,
  operator_id TEXT,
  invite INTEGER NOT NULL,
  state TEXT NOT NULL CHECK(state IN('invited','active','inactive','conflict'))
);
CREATE TABLE bs_audit (
  id INTEGER PRIMARY KEY,
  actor TEXT NOT NULL,
  action TEXT NOT NULL,
  field TEXT,
  changed_at TEXT NOT NULL
);
-- An INSERT of NULL fails the transaction if a concurrent write invalidated its fence.
CREATE TABLE bs_assert (value INTEGER NOT NULL);

CREATE TABLE porthole_notebook_publications (
 id TEXT PRIMARY KEY, notebook_id TEXT NOT NULL REFERENCES porthole_notebooks(id),
 source_revision INTEGER NOT NULL CHECK(source_revision>0), owner_ref TEXT NOT NULL,
 owner_revision INTEGER NOT NULL, operator_version INTEGER NOT NULL,
 projection TEXT NOT NULL CHECK(json_valid(projection)), source_review TEXT NOT NULL CHECK(json_valid(source_review)),
 expires_at INTEGER NOT NULL, digest TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('draft','published','revoked','quarantined')),
 revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
 approved_at INTEGER, revoked_at INTEGER
);
CREATE TRIGGER porthole_notebook_publication_immutable BEFORE UPDATE ON porthole_notebook_publications
 WHEN NEW.id!=OLD.id OR NEW.notebook_id!=OLD.notebook_id OR NEW.source_revision!=OLD.source_revision
 OR NEW.owner_ref!=OLD.owner_ref OR NEW.owner_revision!=OLD.owner_revision OR NEW.operator_version!=OLD.operator_version
 OR NEW.projection!=OLD.projection OR NEW.source_review!=OLD.source_review OR NEW.expires_at!=OLD.expires_at
 OR NEW.digest!=OLD.digest OR NEW.created_at!=OLD.created_at
 BEGIN SELECT RAISE(ABORT,'immutable_notebook_publication'); END;
CREATE TRIGGER porthole_notebook_publication_created AFTER INSERT ON porthole_notebook_publications BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,'notebooks.publication-preview',NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;
CREATE TRIGGER porthole_notebook_publication_changed AFTER UPDATE ON porthole_notebook_publications BEGIN
 INSERT INTO porthole_audit_facts SELECT lower(hex(randomblob(16))),COALESCE((SELECT MAX(ordinal) FROM porthole_audit_facts),0)+1,operation_ref,actor_ref,actor_revision,CASE WHEN NEW.state='published' THEN 'notebooks.publication-approve' ELSE 'notebooks.publication-revoke' END,NEW.id,NEW.revision,occurred_at,CAST(unixepoch('subsec')*1000 AS INTEGER) FROM porthole_audit_context;
END;

ALTER TABLE bs_settings ADD COLUMN owner_id TEXT CHECK(owner_id IS NULL OR owner_id <> '');
ALTER TABLE bs_team ADD COLUMN business_id TEXT CHECK(business_id IS NULL OR business_id <> '');
ALTER TABLE bs_team ADD COLUMN business_role TEXT CHECK(business_role IS NULL OR business_role IN('admin','member'));
CREATE UNIQUE INDEX bs_team_business_id ON bs_team(business_id) WHERE business_id IS NOT NULL;

-- Host identity is explicit and bound to one authenticated collector scope.
CREATE TABLE porthole_host_sources (
 credential_id TEXT NOT NULL REFERENCES porthole_credentials(id), collector_id TEXT NOT NULL,
 team TEXT NOT NULL, service TEXT NOT NULL, environment TEXT NOT NULL, signal TEXT NOT NULL,
 host_id TEXT NOT NULL, first_at INTEGER NOT NULL, last_at INTEGER NOT NULL,
 PRIMARY KEY(credential_id,collector_id,team,service,environment,signal)
);
CREATE TABLE porthole_host_heartbeats (
 id TEXT PRIMARY KEY, credential_id TEXT NOT NULL, collector_id TEXT NOT NULL,
 team TEXT NOT NULL, service TEXT NOT NULL, environment TEXT NOT NULL, signal TEXT NOT NULL,
 host_id TEXT NOT NULL, observed_at INTEGER NOT NULL
);
CREATE INDEX porthole_host_heartbeat_window ON porthole_host_heartbeats(host_id,signal,observed_at);
CREATE TABLE porthole_host_monitor_versions (
 object_id TEXT NOT NULL REFERENCES porthole_objects(id), revision INTEGER NOT NULL,
 name TEXT NOT NULL, scope TEXT NOT NULL CHECK(json_valid(scope)), body TEXT NOT NULL CHECK(json_valid(body)),
 created_at INTEGER NOT NULL, PRIMARY KEY(object_id,revision)
);
CREATE TABLE porthole_host_monitor_state (
 object_id TEXT NOT NULL REFERENCES porthole_objects(id), revision INTEGER NOT NULL, host_id TEXT NOT NULL,
 evaluated_at INTEGER NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence)),
 PRIMARY KEY(object_id,host_id)
);
CREATE TABLE porthole_host_monitor_evaluations (
 id TEXT PRIMARY KEY, object_id TEXT NOT NULL REFERENCES porthole_objects(id), revision INTEGER NOT NULL,
 host_id TEXT NOT NULL, evaluated_at INTEGER NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence))
);
CREATE INDEX porthole_host_monitor_history ON porthole_host_monitor_evaluations(object_id,evaluated_at);
